/**
 * useSync Composable
 *
 * Adapts the singleton SyncOrchestrator to Vue's reactive system.
 * Provides real-time progress updates and control methods.
 */

import { ref, onMounted, onUnmounted, computed } from "vue";
import { syncOrchestrator } from "@/shared/sync/SyncOrchestrator";
import type { SyncState } from "@/shared/sync/types";

export function useSync() {
  const state = ref<SyncState>(syncOrchestrator.getState());

  // Calculate percentage
  const progress = computed(() => {
    const { tablesCompleted, tablesTotal } = state.value.progress;
    if (tablesTotal === 0) return 0;
    // Base percentage on tables completed
    const base = (tablesCompleted / tablesTotal) * 100;
    return Math.min(Math.round(base), 100);
  });

  const isSyncing = computed(() => state.value.isRunning);
  const currentTable = computed(() => state.value.progress.currentTable);
  const errors = computed(() => state.value.errors);
  const hasError = computed(() => state.value.errors.length > 0);

  let unsubscribe: (() => void) | null = null;

  onMounted(() => {
    // Initial state
    state.value = syncOrchestrator.getState();

    // Subscribe to updates
    unsubscribe = syncOrchestrator.subscribe((newState) => {
      state.value = newState;
    });
  });

  onUnmounted(() => {
    if (unsubscribe) {
      unsubscribe();
    }
  });

  const startSync = async () => {
    await syncOrchestrator.startSync();
  };

  const abortSync = () => {
    syncOrchestrator.abort();
  };

  return {
    state,
    progress,
    isSyncing,
    currentTable,
    errors,
    hasError,
    startSync,
    abortSync,
  };
}
