import { useApi } from "@/shared/composables/utils/useApi";

export interface AuthResult {
  access_token: string;
  expires_in: number;
  session_id: string;
}

export interface LoginFormInput {
  login: string;
  password: string;
  db: string;
}

export function useAuthenticate() {
  const query = useApi<AuthResult>();

  const execute = (form: LoginFormInput) => {
    return query.execute("/api/user/authenticate", {
      method: "POST",
      data: form,
    });
  };

  return {
    ...query,
    execute,
  };
}
