<template>
  <f7-page class="bg-gray-50 dark:bg-slate-950">
    <f7-navbar title="Sync Errors" back-link>
      <f7-nav-right>
        <f7-link
          icon-f7="trash"
          color="red"
          @click="confirmClear"
          v-if="errors.length > 0"
        ></f7-link>
      </f7-nav-right>
    </f7-navbar>

    <div
      v-if="errors.length === 0"
      class="flex flex-col items-center justify-center h-full opacity-60 px-8 text-center"
    >
      <div
        class="w-16 h-16 bg-gray-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-4"
      >
        <i class="icon f7-icons text-gray-400">check_mark_circled</i>
      </div>
      <h3 class="text-lg font-medium">No errors recorded</h3>
      <p class="text-sm mt-1 text-gray-400">
        Your synchronization process has been smooth lately.
      </p>
    </div>

    <f7-list v-else media-list no-hairlines-between class="my-0">
      <f7-list-item
        v-for="(error, index) in errors.slice().reverse()"
        :key="index"
        :title="`Table: ${error.table}`"
        :subtitle="formatDate(error.occurredAt)"
        :text="error.error"
        swipeout
      >
        <template #media>
          <div
            class="w-10 h-10 rounded-lg bg-red-100 dark:bg-red-500/20 flex items-center justify-center"
          >
            <i class="icon f7-icons text-red-500 text-lg"
              >exclamationmark_triangle_fill</i
            >
          </div>
        </template>

        <f7-swipeout-actions right>
          <f7-swipeout-button @click="copyOne(error)" color="blue"
            >Copy</f7-swipeout-button
          >
        </f7-swipeout-actions>
      </f7-list-item>
    </f7-list>

    <!-- FAB for Actions -->
    <f7-fab v-if="errors.length > 0" position="right-bottom" color="blue">
      <f7-icon f7="plus"></f7-icon>
      <f7-icon f7="xmark"></f7-icon>
      <f7-fab-buttons position="top">
        <f7-fab-button label="Copy All" @click="copyAll">
          <f7-icon f7="doc_on_doc_fill"></f7-icon>
        </f7-fab-button>
        <f7-fab-button label="Share" @click="share">
          <f7-icon f7="square_arrow_up_fill"></f7-icon>
        </f7-fab-button>
      </f7-fab-buttons>
    </f7-fab>
  </f7-page>
</template>

<script setup lang="ts">
import { ref, onMounted } from "vue";
import {
  f7,
  f7Page,
  f7Navbar,
  f7NavRight,
  f7Link,
  f7List,
  f7ListItem,
  f7Icon,
  f7Fab,
  f7FabButtons,
  f7FabButton,
  f7SwipeoutActions,
  f7SwipeoutButton,
} from "framework7-vue";
import { syncOrchestrator } from "@/shared/sync/SyncOrchestrator";
import { Clipboard } from "@capacitor/clipboard";
import { Share } from "@capacitor/share";
import { useAuthStore } from "@/shared/stores/auth.store";
import { useServerStore } from "@/shared/stores/server.store";

const errors = ref(syncOrchestrator.getPersistentErrors());
const authStore = useAuthStore();
const serverStore = useServerStore();

const formatDate = (isoStr: string) => {
  try {
    const d = new Date(isoStr);
    return d.toLocaleString();
  } catch (e) {
    return isoStr;
  }
};

const getDebugHeader = () => {
  const user = authStore.user;
  const server = serverStore.currentServer;
  return [
    `[User] ${user?.name || "Unknown"}`,
    `[Server] ${server?.name || "Unknown"}`,
    `[Address] ${server?.address || "Unknown"}`,
    `[App Version] ${import.meta.env.VITE_VERSION || "1.0.0"}`,
    `----------------------------------------`,
    "",
  ].join("\n");
};

const formatError = (e: any) => {
  return `[${formatDate(e.occurredAt)}] TABLE: ${e.table}\nERROR: ${e.error}\nRUID: ${e.ruid || "N/A"}`;
};

const copyOne = async (error: any) => {
  await Clipboard.write({
    string: formatError(error),
  });
  f7.toast
    .create({ text: "Error copied to clipboard", closeTimeout: 2000 })
    .open();
};

const copyAll = async () => {
  const content = errors.value.map(formatError).reverse().join("\n\n");
  await Clipboard.write({
    string: getDebugHeader() + content,
  });
  f7.toast
    .create({ text: "All errors copied with system info", closeTimeout: 2000 })
    .open();
};

const share = async () => {
  const content = errors.value.map(formatError).reverse().join("\n\n");
  await Share.share({
    title: "Sync Error Logs",
    text: getDebugHeader() + content,
    dialogTitle: "Share Sync Logs",
  });
};

const confirmClear = () => {
  f7.dialog.confirm(
    "Are you sure you want to clear all sync logs?",
    "Clear Logs",
    async () => {
      await syncOrchestrator.clearErrors();
      errors.value = [];
    },
  );
};

onMounted(() => {
  // Refresh if needed
  errors.value = syncOrchestrator.getPersistentErrors();
});
</script>
