import { useApi } from "@/shared/composables/utils/useApi";

export interface MeResult {
  _ruid: string;
  partner_id: number;
  name: string;
  permissions?: string[];
}

export function useMe() {
  const query = useApi<MeResult>("/api/me");

  return {
    ...query,
    execute: () => query.execute(undefined, { method: "GET" }),
  };
}
