<template>
  <F7Page login-screen no-toolbar no-navbar no-swipeback>
    <F7LoginScreenTitle>Efficy Sync</F7LoginScreenTitle>
    <F7List form>
      <F7ListInput
        label="Username"
        type="text"
        placeholder="Your username"
        :value="form.login"
        @input="form.login = $event.target.value"
      ></F7ListInput>
      <F7ListInput
        label="Password"
        type="password"
        placeholder="Your password"
        :value="form.password"
        @input="form.password = $event.target.value"
      ></F7ListInput>
      <F7ListInput
        label="Database"
        type="text"
        placeholder="Database name"
        :value="form.db"
        @input="form.db = $event.target.value"
      ></F7ListInput>
    </F7List>
    <div class="padding">
      <F7Button preloader fill large @click="signIn" :loading="loading">
        {{ "Sign In" }}
      </F7Button>
      <F7BlockFooter>
        <p>Server: {{ currentServer?.name || "Not Configured" }}</p>
      </F7BlockFooter>
      <div class="margin-top text-align-center">
        <F7Link @click="openServerConfig">Configure Server</F7Link>
      </div>
    </div>

    <ServerConfigPopup v-model:opened="showServerConfig" />
  </F7Page>
</template>

<script setup lang="ts">
import { reactive, ref, computed } from "vue";
import { useAuth } from "../composables/useAuth";
import { useServerStore } from "@/shared/stores/server.store";
import ServerConfigPopup from "@/modules/auth/components/ServerConfigPopup.vue"; // We need this component

const { login, loading, syncStatus } = useAuth();
const serverStore = useServerStore();

const showServerConfig = ref(false);

const form = reactive({
  login: "",
  password: "",
  db: "",
});

const currentServer = computed(() => serverStore.currentServer);

const signIn = async () => {
  if (!serverStore.baseUrl) {
    showServerConfig.value = true;
    return;
  }
  await login(form);
};

const openServerConfig = () => {
  showServerConfig.value = true;
};
</script>
