import type { Router } from "framework7/types";

const syncRoutes: Router.RouteParameters[] = [
  {
    path: "/sync",
    name: "SyncProcess",
    async({ resolve }) {
      import("@/modules/sync/views/SyncProcess.vue").then((vc) => {
        resolve({ component: vc.default });
      });
    },
  },
  {
    path: "/settings/sync-errors",
    name: "SyncErrors",
    async({ resolve }) {
      import("@/modules/sync/views/SyncErrorsView.vue").then((vc) => {
        resolve({ component: vc.default });
      });
    },
  },
];

export default syncRoutes;
